Let me sweep two-phase sequences (drive right to build speed, then charge left) using the free `observe`.

```python
import numpy as np
def ev(seq):
    obs,_ = observe(params=None, actions=list(seq), n_steps=len(seq))
    blue=obs[:,26:28]; green=obs[:,234:236]; red=obs[:,104:106]
    dx=np.maximum(np.abs(green[:,0]-blue[:,0])-0.207,0)
    dy=np.maximum(np.abs(green[:,1]-blue[:,1])-0.382,0)
    tb=np.hypot(dx,dy)<=0.22
    dxr=np.maximum(np.abs(green[:,0]-red[:,0])-0.442,0)
    dyr=np.maximum(np.abs(green[:,1]-red[:,1])-0.05,0)
    tr=np.hypot(dxr,dyr)<=0.22
    if tb.any(): return ('success', int(np.where(tb)[0][0]), float(green[:,0].min()))
    if tr.any():
        it=int(np.where(tr)[0][0]); return ('red', it, float(green[:it+1,0].min()))
    return ('ok', len(seq), float(green[:,0].min()))

suc=[]; best=('none',None,1e9)
for p in range(0,52,4):
    for q in range(16,124,4):
        r=ev([2]*p+[1]*q)
        if r[0]=='success': suc.append((p,q,r))
        if r[2]<best[2]: best=(p,q,r)
print("successes:", suc[:10])
print("best", best)
```

