The successful sequence is `[2]*8 + [1]*`: drive right ~8 steps to build momentum, then charge left. The network never does this. Let me test whether a simple state-based policy can replicate it.

```python
import numpy as np
def sim_policy(policy, maxsteps=90):
    actions=[]
    obs=observe(params=None, actions=[0], n_steps=1)[0]
    state=obs[0]
    for t in range(maxsteps):
        a=policy(state); actions.append(a)
        obs=observe(params=None, actions=actions, n_steps=len(actions))[0]
        state=obs[-1]
        g=state[234:236]; b=state[26:28]; r=state[104:106]
        dx=max(abs(g[0]-b[0])-0.207,0); dy=max(abs(g[1]-b[1])-0.382,0)
        if np.hypot(dx,dy)<=0.22: return ('success',t)
        dxr=max(abs(g[0]-r[0])-0.442,0); dyr=max(abs(g[1]-r[1])-0.05,0)
        if np.hypot(dxr,dyr)<=0.22: return ('red',t)
    return ('timeout',maxsteps)
def mk(cond):
    return lambda s: 2 if cond(s) else 1
pols={
 'green_y<0.62': mk(lambda s: s[235]<0.62),
 'carvel>=0': mk(lambda s: s[54]>=0),
 'green_x>2.5': mk(lambda s: s[234]>2.5),
 'car_x<3.1': mk(lambda s: s[52]<3.1),
 'carvel>=0.3': mk(lambda s: s[54]>=0.3),
}
for n,p in pols.items(): print(n, sim_policy(p))
